// Host test of AtcMirrorProtocol.h against the golden vectors (vectors.h, generated by gen_vectors.py).
//   g++ -std=c++17 -Wall -Wextra -I../../src protocol_test.cpp -o protocol_test && ./protocol_test
// Exit code 0 when every check passes.
#include <cstdio>
#include <cstring>

#include "AtcMirrorProtocol.h"
#include "vectors.h"

using namespace atc_mirror;

static int g_failures = 0;
static int g_checks = 0;

static void check(bool condition, const char* what, const char* name) {
  ++g_checks;
  if (!condition) {
    ++g_failures;
    std::printf("FAIL %s: %s\n", name, what);
  }
}

static uint16_t readU16le(const uint8_t* p) {
  return static_cast<uint16_t>(p[0] | (p[1] << 8));
}

static uint32_t readU32le(const uint8_t* p) {
  return static_cast<uint32_t>(p[0]) | (static_cast<uint32_t>(p[1]) << 8) | (static_cast<uint32_t>(p[2]) << 16) |
         (static_cast<uint32_t>(p[3]) << 24);
}

static void testCrcCheckValue() {
  const uint8_t* text = reinterpret_cast<const uint8_t*>(kCrcCheckInput);
  check(crc16(text, std::strlen(kCrcCheckInput)) == kCrcCheckValue, "crc16(\"123456789\") == 0x29B1", "crc");
  // The same CRC fed in two parts.
  uint16_t crc = crcUpdate(kCrcInit, text, 4);
  crc = crcUpdate(crc, text + 4, 5);
  check(crc == kCrcCheckValue, "crcUpdate in two parts", "crc");
}

static void testEncode(const GoldenVector& v) {
  uint8_t out[512];
  size_t n = encode(v.displayId, v.type, v.payload, v.payloadLength, out, sizeof(out), v.flags);
  check(n == v.packetLength, "encode() returns the packet length", v.name);
  check(n == v.packetLength && std::memcmp(out, v.packet, n) == 0, "encode() bytes equal packetHex", v.name);

  // Exactly the packet size fits; one byte less does not.
  uint8_t exact[512];
  check(encode(v.displayId, v.type, v.payload, v.payloadLength, exact, v.packetLength, v.flags) == v.packetLength,
        "encode() into an exactly sized buffer", v.name);
  check(encode(v.displayId, v.type, v.payload, v.payloadLength, exact, v.packetLength - 1, v.flags) == 0,
        "encode() returns 0 when the buffer is one byte short", v.name);
}

static void testStreaming(const GoldenVector& v, size_t chunk) {
  uint8_t out[512];
  size_t pos = 0;
  uint8_t header[kHeaderSize];
  encodeHeader(v.displayId, v.type, static_cast<uint32_t>(v.payloadLength), header, v.flags);
  uint16_t crc = headerCrc(header);
  std::memcpy(out + pos, header, kHeaderSize);
  pos += kHeaderSize;
  for (size_t offset = 0; offset < v.payloadLength; offset += chunk) {
    size_t n = v.payloadLength - offset < chunk ? v.payloadLength - offset : chunk;
    crc = crcUpdate(crc, v.payload + offset, n);
    std::memcpy(out + pos, v.payload + offset, n);
    pos += n;
  }
  uint8_t tail[kCrcSize];
  encodeCrc(crc, tail);
  std::memcpy(out + pos, tail, kCrcSize);
  pos += kCrcSize;
  check(pos == v.packetLength && std::memcmp(out, v.packet, pos) == 0, "streaming encode equals packetHex", v.name);
}

static void testColorConversion() {
  // color-frame-2x2: payload 02 00 02 00 | F8 00 07 E0 00 1F FF FF
  const GoldenVector* color = 0;
  for (size_t i = 0; i < kVectorCount; ++i) {
    if (std::strcmp(kVectors[i].name, "color-frame-2x2") == 0) {
      color = &kVectors[i];
    }
  }
  check(color != 0, "color-frame-2x2 vector present", "rgb565");
  if (color == 0) {
    return;
  }
  const uint8_t* expected = color->payload + 4;

  // Ordinary uint16_t values (pixelsAreBigEndian = false).
  const uint16_t values[4] = {0xF800, 0x07E0, 0x001F, 0xFFFF};
  uint8_t wire[8];
  rgb565ToWire(values, 4, false, wire);
  check(std::memcmp(wire, expected, 8) == 0, "native values -> big-endian bytes", "rgb565");

  // Memory already high byte first (TFT_eSPI sprite style): bytes are copied unchanged.
  uint16_t swapped[4];
  std::memcpy(swapped, expected, 8);
  uint8_t wire2[8];
  rgb565ToWire(swapped, 4, true, wire2);
  check(std::memcmp(wire2, expected, 8) == 0, "big-endian memory copied unchanged", "rgb565");

  uint8_t size[4];
  encodeFrameSize(2, 2, size);
  check(std::memcmp(size, color->payload, 4) == 0, "encodeFrameSize(2, 2)", "rgb565");
}

static void testSizes() {
  check(monoFrameBytes(8, 8) == 8, "monoFrameBytes(8, 8) == 8", "sizes");
  check(monoFrameBytes(128, 64) == 1024, "monoFrameBytes(128, 64) == 1024", "sizes");
  check(monoFrameBytes(128, 65) == 1152, "monoFrameBytes(128, 65) == 1152", "sizes");
  check(epaperPlaneBytes(8, 2) == 2, "epaperPlaneBytes(8, 2) == 2", "sizes");
  check(epaperPlaneBytes(122, 250) == 4000, "epaperPlaneBytes(122, 250) == 4000", "sizes");
  check(colorFrameBytes(65535, 65535) == 8589672450ULL, "colorFrameBytes does not overflow", "sizes");
  check(maxPayload(MessageType::ColorFrame) == 4194304UL, "frame cap", "sizes");
  check(maxPayload(MessageType::Data) == 65536UL, "small cap", "sizes");
  check(packetSize(0) == 12, "packetSize(0) == 12", "sizes");
}

static void testCaps() {
  static uint8_t payload[65537];
  static uint8_t out[65537 + kPacketOverhead];
  check(encode(0, MessageType::Data, payload, 65536, out, sizeof(out)) == 65536 + kPacketOverhead,
        "a 65,536-byte Data payload is encoded", "caps");
  check(encode(0, MessageType::Data, payload, 65537, out, sizeof(out)) == 0, "a 65,537-byte Data payload is refused",
        "caps");
  check(encode(0, MessageType::Data, 0, 3, out, sizeof(out)) == 0, "a null payload with a length is refused", "caps");
  check(encode(0, MessageType::Reset, 0, 0, out, sizeof(out)) == kPacketOverhead, "a null empty payload is fine",
        "caps");
}

static void testRejects() {
  for (size_t i = 0; i < kRejectCount; ++i) {
    const RejectVector& r = kRejects[i];
    if (r.packetLength < kPacketOverhead) {
      check(std::strcmp(r.reason, "Truncated") == 0, "short packet is Truncated", r.name);
      continue;
    }
    uint32_t declared = readU32le(r.packet + 6);
    uint8_t type = r.packet[4];
    bool lengthMatches = declared == r.packetLength - kPacketOverhead;
    bool crcOk = lengthMatches && readU16le(r.packet + r.packetLength - 2) ==
                                      crc16(r.packet + 2, r.packetLength - 2 - kCrcSize);
    if (std::strcmp(r.reason, "BadCrc") == 0) {
      check(lengthMatches && !crcOk, "CRC does not match", r.name);
    } else if (std::strcmp(r.reason, "UnsupportedVersion") == 0) {
      check(crcOk && r.packet[2] != kVersion, "valid CRC, other version", r.name);
    } else if (std::strcmp(r.reason, "UnknownType") == 0) {
      check(crcOk && !isKnownType(type), "valid CRC, unknown type", r.name);
    } else if (std::strcmp(r.reason, "TooLarge") == 0) {
      check(declared > maxPayload(type), "declared length over the cap of the type", r.name);
    } else if (std::strcmp(r.reason, "Truncated") == 0) {
      check(declared > r.packetLength - kPacketOverhead, "declared more than present", r.name);
    } else if (std::strcmp(r.reason, "Malformed") == 0) {
      check(r.packet[0] != kMagic0 || r.packet[1] != kMagic1 || declared < r.packetLength - kPacketOverhead,
            "bad magic or trailing bytes", r.name);
    } else {
      check(false, "unknown reason in vectors.h", r.name);
    }
  }
}

int main() {
  testCrcCheckValue();
  for (size_t i = 0; i < kVectorCount; ++i) {
    testEncode(kVectors[i]);
    testStreaming(kVectors[i], 1);
    testStreaming(kVectors[i], 7);
    testStreaming(kVectors[i], 64);
    check(isKnownType(kVectors[i].type), "type is known", kVectors[i].name);
  }
  testColorConversion();
  testSizes();
  testCaps();
  testRejects();
  std::printf("%s: %d checks, %d failures (%u vectors, %u rejects)\n", g_failures == 0 ? "OK" : "FAILED", g_checks,
              g_failures, static_cast<unsigned>(kVectorCount), static_cast<unsigned>(kRejectCount));
  return g_failures == 0 ? 0 : 1;
}
